 public static HtkkAutomationStage GetFilenameStage(bool opening, HtkkFilenameDialogAction action) {
  if (opening) {
   switch (action) {
    case HtkkFilenameDialogAction.FocusWaiting: return HtkkAutomationStage.GtgtImportFilenameFocusWaiting;
    case HtkkFilenameDialogAction.FocusTimeout: return HtkkAutomationStage.GtgtImportFilenameFocusTimeout;
    case HtkkFilenameDialogAction.KeyboardEditing: return HtkkAutomationStage.GtgtImportFilenameKeyboardEditing;
    case HtkkFilenameDialogAction.KeyboardFocused: return HtkkAutomationStage.GtgtImportFilenameKeyboardFocused;
    case HtkkFilenameDialogAction.KeyboardSelected: return HtkkAutomationStage.GtgtImportFilenameKeyboardSelected;
    case HtkkFilenameDialogAction.KeyboardTyped: return HtkkAutomationStage.GtgtImportFilenameKeyboardTyped;
    default: throw new ArgumentException("Unknown filename action");
   }
  } else {
   switch (action) {
    case HtkkFilenameDialogAction.FocusWaiting: return HtkkAutomationStage.GtgtExportFilenameFocusWaiting;
    case HtkkFilenameDialogAction.FocusTimeout: return HtkkAutomationStage.GtgtExportFilenameFocusTimeout;
    case HtkkFilenameDialogAction.KeyboardEditing: return HtkkAutomationStage.GtgtExportFilenameKeyboardEditing;
    case HtkkFilenameDialogAction.KeyboardFocused: return HtkkAutomationStage.GtgtExportFilenameKeyboardFocused;
    case HtkkFilenameDialogAction.KeyboardSelected: return HtkkAutomationStage.GtgtExportFilenameKeyboardSelected;
    case HtkkFilenameDialogAction.KeyboardTyped: return HtkkAutomationStage.GtgtExportFilenameKeyboardTyped;
    default: throw new ArgumentException("Unknown filename action");
   }
  }
 }
 public static HtkkAutomationStage GetMenuClickStage(string menuId) {
   if (menuId == "101") return HtkkAutomationStage.GtgtMenuClick101;
   if (menuId == "101_1") return HtkkAutomationStage.GtgtMenuClick101_1;
   if (menuId == "D1") return HtkkAutomationStage.GtgtMenuClickD1;
  throw new ArgumentException("Unknown menu ID for click stage");
 }
